class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError(
                f"Rolls cannot score negative points or more than 10 points: got {pins}"
            )

        if self._game_over():
            raise ValueError("Cannot roll after the game has ten frames")

        self.rolls.append(pins)
        self._validate_frame()

    def score(self):
        if not self._game_over():
            raise ValueError("Cannot score an incomplete game")
        return self._calculate_score()

    def _game_over(self):
        rolls = self.rolls
        i = 0
        for frame in range(10):
            if i >= len(rolls):
                return False
            if frame < 9:
                i += 1 if rolls[i] == 10 else 2
            else:
                first = rolls[i]
                if first == 10:
                    return len(rolls) == i + 3
                if i + 1 < len(rolls) and first + rolls[i + 1] == 10:
                    return len(rolls) == i + 3
                return len(rolls) == i + 2

    def _validate_frame(self):
        rolls = self.rolls
        i = 0
        for frame in range(10):
            if i >= len(rolls):
                break
            if frame < 9:
                if rolls[i] != 10 and i + 1 < len(rolls) and rolls[i] + rolls[i + 1] > 10:
                    raise ValueError(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
            else:
                first = rolls[i]
                if first == 10 and i + 2 < len(rolls):
                    second = rolls[i + 1]
                    if second != 10 and second + rolls[i + 2] > 10:
                        raise ValueError(
                            "Two bonus rolls after a strike cannot score more than "
                            "10 points unless the first is a strike"
                        )
                elif first != 10 and i + 1 < len(rolls) and first + rolls[i + 1] > 10:
                    raise ValueError(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
            i += 1 if rolls[i] == 10 else 2

    def _calculate_score(self):
        rolls = self.rolls
        score = 0
        i = 0
        for frame in range(10):
            if rolls[i] == 10:
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                score += 10 + rolls[i + 2]
                i += 2
            else:
                score += rolls[i] + rolls[i + 1]
                i += 2
        return score

